1	package cli
2	
3	import (
4		"fmt"
5		"os"
6		"path/filepath"
7		"strings"
8	
9		"github.com/okf-memory/okf-agent-memory/pkg/lock"
10		"github.com/okf-memory/okf-agent-memory/pkg/registry"
11	)
12	
13	var exitFunc = os.Exit
14	
15	func printVendorUsage() {
16		fmt.Println(`Usage:
17	  okf vendor <command>
18	
19	Commands:
20	  list     List installed vendor bundles
21	  remove   Uninstall a vendor bundle (okf vendor remove <bundle-id>)
22	
23	Examples:
24	  okf vendor list
25	  okf vendor remove nextjs-15
26	  okf vendor remove @peter/django-5-rules`)
27	}
28	
29	func cmdVendor(args []string) {
30		if len(args) == 0 {
31			printVendorUsage()
32			return
33		}
34	
35		switch args[0] {
36		case "list":
37			lf, err := lock.ReadLockfile("okf.lock")
38			if err != nil || len(lf.Bundles) == 0 {
39				fmt.Println("No vendor bundles installed.")
40				return
41			}
42			fmt.Printf("Installed Vendor Bundles (%d):\n", len(lf.Bundles))
43			for _, b := range lf.Bundles {
44				fmt.Printf("  - %-24s %-10s (%s)\n", b.ID, b.Version, b.Source)
45			}
46	
47		case "remove":
48			if len(args) < 2 {
49				fmt.Fprintln(os.Stderr, "Usage: okf vendor remove <bundle-id>")
50				exitFunc(1)
51				return
52			}
53			bundleID := strings.TrimPrefix(args[1], "@")
54			// Removal is recursive, so the id must resolve inside .okf/vendor.
55			vendorDir, err := registry.ResolveVendorDir(".", bundleID)
56			if err != nil {
57				fmt.Fprintf(os.Stderr, "Error: refusing to remove vendor bundle: %v\n", err)
58				exitFunc(1)
59				return
60			}
61	
62			lf, err := lock.ReadLockfile("okf.lock")
63			lockHasBundle := false
64			if err == nil && lf != nil {
65				for _, b := range lf.Bundles {
66					if b.ID == bundleID {
67						lockHasBundle = true
68						break
69					}
70				}
71			}
72	
73			// A directory is only considered an installed bundle if it contains index.md.
74			// Subdirectories without index.md (e.g. parent namespace or organization dirs)
75			// are not valid bundles and must not be removed by partial matches.
76			isBundleDir := false
77			if info, err := os.Stat(vendorDir); err == nil && info.IsDir() {
78				if _, err := os.Stat(filepath.Join(vendorDir, "index.md")); err == nil {
79					isBundleDir = true
80				}
81			}
82	
83			if !isBundleDir && !lockHasBundle {
84				var suggestions []string
85				if lf != nil {
86					for _, b := range lf.Bundles {
87						if strings.HasPrefix(b.ID, bundleID+"/") || strings.Contains(b.ID, bundleID) {
88							suggestions = append(suggestions, b.ID)
89						}
90					}
91				}
92				if len(suggestions) > 0 {
93					fmt.Fprintf(os.Stderr, "Error: vendor bundle %q is not installed. Did you mean %q?\n", bundleID, suggestions[0])
94				} else {
95					fmt.Fprintf(os.Stderr, "Error: vendor bundle %q is not installed\n", bundleID)
96				}
97				exitFunc(1)
98				return
99			}
100	
101			if isBundleDir {
102				if err := registry.RemoveVendorDir(".", bundleID); err != nil {
103					fmt.Fprintf(os.Stderr, "Error: refusing to remove vendor bundle: %v\n", err)
104					exitFunc(1)
105					return
106				}
107			}
108	
109			if lockHasBundle && lf != nil {
110				if lf.Remove(bundleID) {
111					if len(lf.Bundles) == 0 {
112						_ = os.Remove("okf.lock")
113					} else {
114						if err := lock.WriteLockfile("okf.lock", lf); err != nil {
115							fmt.Fprintf(os.Stderr, "Warning: failed to update okf.lock: %v\n", err)
116						}
117					}
118				}
119			}
120			fmt.Printf("Removed vendor bundle %s\n", bundleID)
121	
122		default:
123			printVendorUsage()
124		}
125	}
